def solve(board):
    """
    Modifies the board in-place by flipping surrounded 'O's to 'X'.
    """
    if not board or not board[0]:
        return

    rows, cols = len(board), len(board[0])

    def dfs(r, c):
        # Out of bounds or not 'O', stop
        if not (0 ≤ r < rows and 0 ≤ c < cols) or board[r][c] != 'O':
            return
        # Mark safe 'O' connected to border as 'E'
        board[r][c] = 'E'
        # Visit all four directions
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)

    # 1. Mark border-connected 'O's as 'E'
    for r in range(rows):
        for c in [0, cols-1]:
            dfs(r, c)
    for c in range(cols):
        for r in [0, rows-1]:
            dfs(r, c)

    # 2. Flip non-border 'O's to 'X', revert 'E' back to 'O'
    for r in range(rows):
        for c in range(cols):
            if board[r][c] == 'O':
                board[r][c] = 'X'
            elif board[r][c] == 'E':
                board[r][c] = 'O'
